        }

        if (role == "Director")
        {
            if (invoice.Amount > 500000m)
            {
                throw new ArgumentException(
                    $"Director approval is limited to invoices up to 500000. Invoice {invoice.Id} amount {invoice.Amount} exceeds the limit.");
