test('Manager approval above 50,000 is rejected and invoice remains pending', async ({ page }) => {
  const customerName = `Manager Limit ${Date.now()}`;

  await createAndSubmitInvoice(page, 'demo.manager', customerName, '50001');
  await approveFromApprovals(page, customerName);

  const errorAlert = page.getByRole('alert').filter({
    hasText: /Manager approval is limited to invoices up to 50000/i,
  });
  await expect(errorAlert).toBeVisible();

  await assertInvoicePending(page, customerName);
});

test('Director approval for a >500,000 invoice requires a second stage and stays pending until final approval', async ({ page }) => {
  const customerName = `Director High Value ${Date.now()}`;

  await createAndSubmitInvoice(page, 'demo.director', customerName, '500001');
  await approveFromApprovals(page, customerName);

  await expect(page.getByRole('alert')).not.toContainText(/limited to invoices up to 500000|For invoices above 500000/i);
  await assertInvoicePending(page, customerName);

  await page.getByRole('button', { name: 'Sign out' }).click();
  await signIn(page, 'demo.director2', 'ChangeMe123!');
  await approveFromApprovals(page, customerName);

  await page.getByRole('tab', { name: 'Invoices' }).click();
  await expect(page.getByRole('row').filter({ hasText: customerName })).toContainText('Approved');
});

test('High-value approvals reject same-user and non-Director second stage attempts without mutating invoice state', async ({ page }) => {
  const sameUserCustomer = `Same User Rejection ${Date.now()}`;
  const nonDirectorCustomer = `Non Director Rejection ${Date.now() + 1}`;

  await createAndSubmitInvoice(page, 'demo.manager', sameUserCustomer, '600001');
  await approveFromApprovals(page, sameUserCustomer);

  await expect(page.getByRole('alert')).toBeHidden();
  await page.getByRole('tab', { name: 'Approvals' }).click();
  const sameUserApprovalItem = page.getByRole('listitem').filter({ hasText: sameUserCustomer });
  await sameUserApprovalItem.getByRole('button', { name: /Approve invoice/i }).click();

  const sameUserError = page.getByRole('alert').filter({
    hasText: /distinct approver usernames|same user/i,
  });
  await expect(sameUserError).toBeVisible();
  await assertInvoicePending(page, sameUserCustomer);

  await page.getByRole('button', { name: 'Sign out' }).click();
  await createAndSubmitInvoice(page, 'demo.director', nonDirectorCustomer, '600001');
  await approveFromApprovals(page, nonDirectorCustomer);

  await page.getByRole('button', { name: 'Sign out' }).click();
  await signIn(page, 'demo.manager', 'ChangeMe123!');
  await approveFromApprovals(page, nonDirectorCustomer);

  const secondStageError = page.getByRole('alert').filter({
    hasText: /second approver must be a Director|Director/i,
  });
  await expect(secondStageError).toBeVisible();
  await assertInvoicePending(page, nonDirectorCustomer);
});

