        # Try several patterns for app.report = { ... }
        m = re.search(r'\"metrics\"\s*:\s*\{(.*?)\}\s*,\s*\"files\"', text)
        if not m:
            m = re.search(r'\"mutationScore\"\s*:\s*([0-9.]+)', text)
        if not m:
            # fallback: find all 'mutationScore' occurrences in a compact js object
            vals = re.findall(r'\"mutationScore\"\s*:\s*([0-9.]+)', text)
